import sys
sys.setrecursionlimit(100000000)
n = int(input())
(r1, c1) = map(int, input().strip().split())
(r2, c2) = map(int, input().strip().split())
r1 -= 1
c1 -= 1
r2 -= 1
c2 -= 1
v = [[0 for i in range(n)] for j in range(n)]
mat = []
for i in range(n):
	r = input()
	mat.append(r)

def dfs(node, color):
	x = node[0]
	y = node[1]
	v[x][y] = color
	for (i, j) in [(-1, 0), (1, 0), (0, 1), (0, -1)]:
		xx = x + i
		yy = y + j
		if xx >= 0 and xx <= n - 1 and (yy >= 0) and (yy <= n - 1) and (mat[x][y] == '0' and mat[xx][yy] == '0' or (mat[x][y] == '1' and mat[xx][yy] == '1')) and (v[xx][yy] == 0):
			dfs((xx, yy), color)
land_cnt = 1
river_cnt = -1
for i in range(n):
	for j in range(n):
		if v[i][j] == 0 and mat[i][j] == '0':
			dfs((i, j), land_cnt)
			land_cnt += 1
		elif v[i][j] == 0 and mat[i][j] == '1':
			dfs((i, j), river_cnt)
			river_cnt -= 1
		else:
			pass
color1 = v[r1][c1]
color2 = v[r2][c2]
L1 = []
L2 = []
for i in range(n):
	for j in range(n):
		if v[i][j] == color1:
			L1.append((i, j))
		elif v[i][j] == color2:
			L2.append((i, j))
res = 50000
if color1 == color2:
	print(0)
else:
	for (k1, v1) in L1:
		for (k2, v2) in L2:
			now = (k1 - k2) ** 2 + (v1 - v2) ** 2
			res = min(res, now)
	print(res)
